import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const countries = JSON.parse(fs.readFileSync(path.join(root, 'src/data/flag-codes.json'), 'utf8'));
const codes = [...new Set(Object.values(countries).map(code => code.toLowerCase()))].sort();
const svgRoot = path.join(root, 'node_modules/flag-icons/flags/4x3');

for (const code of codes) {
  if (!fs.existsSync(path.join(svgRoot, `${code}.svg`))) throw new Error(`Missing flag SVG: ${code}`);
}

const css = [
  '/* Generated by scripts/generate_flag_css.mjs from flag-codes.json. */',
  ...codes.map(code => `.player-flag--${code}{background-image:url('../node_modules/flag-icons/flags/4x3/${code}.svg')}`)
].join('\n') + '\n';
fs.writeFileSync(path.join(root, 'src/flag-icons.css'), css);
console.log(`Generated CSS for ${codes.length} country flags`);
